// Create the log repo if needed (a plain `git init`).
inline void InitEventLogRepo(const std::string& repo) {
  try {
    detail::GitText(repo, {"rev-parse", "--git-dir"});
  } catch (...) {
    std::string cmd = "git init -q " + detail::ShellQuote(repo) +
                      " >/dev/null 2>/dev/null";
    if (std::system(cmd.c_str()) != 0) {
      throw std::runtime_error("git init failed for " + repo);
    }
  }
}

inline std::string BranchHead(const std::string& repo,
                              const std::string& branch) {
  try {
    return detail::GitText(repo, {"rev-parse", "--verify",
                                  "refs/heads/" + branch});
  } catch (...) {
    return "";
  }
}

// "grpc-dc event 42" plus Seq/Publisher/Tag trailers, so
// `git log` alone can filter the log without decoding blobs.
inline std::string CommitMessage(const Event& event) {
  std::string out = std::string(detail::kGitCommitSubject) + " " +
                    std::to_string(event.seq) + "\n\n" +
                    detail::kGitTrailerSeq + ": " +
                    std::to_string(event.seq);
  if (!event.publisher_id.empty()) {
    out += "\n" + std::string(detail::kGitTrailerPublisher) + ": " +
           event.publisher_id;
  }
  for (const auto& tv : event.tags) {
    out += "\n" + std::string(detail::kGitTrailerTag) + ": " +
           TagValueKey(tv);
  }
  return out + "\n";
}

inline std::map<std::string, std::string> CommitEnv(const Event& event) {
  long long seconds = event.timestamp_unix_ms / 1000;
  if (seconds < 0) seconds = 0;
  std::string date = std::to_string(seconds) + " +0000";
  return {{"GIT_AUTHOR_NAME", detail::kGitAuthorName},
          {"GIT_AUTHOR_EMAIL", detail::kGitAuthorEmail},
          {"GIT_COMMITTER_NAME", detail::kGitAuthorName},
          {"GIT_COMMITTER_EMAIL", detail::kGitAuthorEmail},
          {"GIT_AUTHOR_DATE", date},
          {"GIT_COMMITTER_DATE", date}};
}

// Import a branch: events in chain order (oldest first),
// optionally windowed by sequence number and narrowed by a
// tag filter (same containment semantics as Subscribe). A
// missing branch imports as an empty log.
inline std::vector<Event> ImportEvents(
    const std::string& repo, const std::string& branch = kEventLogBranch,
    std::uint64_t from_seq = 0, std::int64_t to_seq = -1,
    const std::vector<TagValue>* filter_tags = nullptr) {
  std::vector<Event> events;
  if (BranchHead(repo, branch).empty()) return events;
  std::string list = detail::GitText(repo, {"rev-list", "--reverse", branch});
  size_t pos = 0;
  while (pos < list.size()) {
    size_t nl = list.find('\n', pos);
    std::string sha = list.substr(pos, nl == std::string::npos ? nl : nl - pos);
    pos = nl == std::string::npos ? list.size() : nl + 1;
    if (sha.empty()) continue;
    std::string data = detail::Git(
        repo, {"cat-file", "-p", sha + ":" + detail::kGitBlobPath});
    Event event;
    event.UnmarshalDc(grpcdc::Bytes(data.begin(), data.end()));
    if (event.seq <= from_seq) continue;
    if (to_seq >= 0 && event.seq > static_cast<std::uint64_t>(to_seq)) continue;
    if (filter_tags != nullptr && !TagsMatch(event.tags, *filter_tags)) continue;
    events.push_back(event);
  }
  return events;
}

// Export events onto the branch: one commit per event, in
// sequence order, skipping sequence numbers the branch
